 "content": "def transform(grid):
    """Recolor full-width/full-height separator lines, preserving other marks."""
    if not grid or not grid[0]:
        return grid
    h, w = len(grid), len(grid[0])
    # Separator color is the color forming complete rows and columns.
    row_colors = {grid[r][0] for r in range(h) if all(v == grid[r][0] for v in grid[r])}
    col_colors = {grid[0][c] for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))}
    candidates = row_colors & col_colors
    if not candidates:
        return [row[:] for row in grid]
    sep = next(iter(candidates))
    out = [row[:] for row in grid]
    for r in range(h):
        if all(v == sep for v in grid[r]):
            out[r] = [2 if v == sep else v for v in out[r]]
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
